// Trace checker: expected path + forbidden shapes (plain JS)
function checkTrace(trace, terminals, gold) {
  const issues = [];
  const path = trace.map((t) => t.split(" -> ")[1]);
  if (!path.includes(gold.expect.terminal)) issues.push("missing-terminal:" + gold.expect.terminal);
  for (const f of gold.forbid || [])
    if (path.join(" ").includes(f.split("-")[0])) issues.push("forbidden:" + f);
  return { pass: issues.length === 0, issues, path };
}
// Attribution: missing terminal → routing/upstream; forbidden → boundary/gate.

