  const issues = [];
  const arrived = path.some((h) => h.endsWith(' -> ' + gold.expect.terminal));
  if (!arrived) issues.push('missing-terminal:' + gold.expect.terminal);
  for (const f of gold.forbid || []) if (path.join(' ').includes(f)) issues.push('forbidden:' + f);
  return { pass: issues.length === 0, issues };
}
